#!/usr/bin/env bash
# GENERATED FILE PRODUCER — see App/Generated/Secrets.swift.
# Reads ~/.config/keys/{enrich.env,.env}, parses only KEY=value lines (never
# sourced — a stray shell construct in a dotenv should not execute), and
# writes the three secrets this app needs into a gitignored Swift file.
#
# Usage:
#   Scripts/generate-secrets.sh            generate App/Generated/Secrets.swift
#   Scripts/generate-secrets.sh --check    verify the anti-leak property, exit 1 if broken
set -euo pipefail
cd "$(dirname "$0")/.."

REPO_ROOT="$(pwd)"
OUT_DIR="$REPO_ROOT/App/Generated"
OUT_FILE="$OUT_DIR/Secrets.swift"

check_mode=false
if [ "${1:-}" = "--check" ]; then
    check_mode=true
fi

if [ "$check_mode" = true ]; then
    ok=true
    if ! git check-ignore -q "App/Generated/Secrets.swift"; then
        echo "LEAK CHECK FAILED: App/Generated/Secrets.swift is NOT gitignored." >&2
        ok=false
    fi
    if [ -n "$(git ls-files App/Generated/ 2>/dev/null)" ]; then
        echo "LEAK CHECK FAILED: git is tracking files under App/Generated/." >&2
        ok=false
    fi
    if [ "$ok" = false ]; then
        exit 1
    fi
    echo "Leak check passed: App/Generated/ is ignored and untracked."
    exit 0
fi

# Extract KEY=value for one key out of a dotenv file, without sourcing it.
# Strips inline comments-free values as-is; trims surrounding quotes.
extract_key() {
    local file="$1" key="$2"
    [ -f "$file" ] || return 0
    grep -E "^${key}=" "$file" 2>/dev/null | tail -n1 | cut -d'=' -f2- | sed -e 's/^"//' -e 's/"$//' -e "s/^'//" -e "s/'$//"
}

ENRICH_ENV="$HOME/.config/keys/enrich.env"
DOT_ENV="$HOME/.config/keys/.env"

discogs_token="$(extract_key "$ENRICH_ENV" "DISCOGS_TOKEN")"
sc_client_id="$(extract_key "$DOT_ENV" "SOUNDCLOUD_CLIENT_ID")"
sc_client_secret="$(extract_key "$DOT_ENV" "SOUNDCLOUD_CLIENT_SECRET")"

[ -n "$discogs_token" ] || echo "warning: DISCOGS_TOKEN not found in $ENRICH_ENV — emitting empty string"
[ -n "$sc_client_id" ] || echo "warning: SOUNDCLOUD_CLIENT_ID not found in $DOT_ENV — emitting empty string"
[ -n "$sc_client_secret" ] || echo "warning: SOUNDCLOUD_CLIENT_SECRET not found in $DOT_ENV — emitting empty string"

mkdir -p "$OUT_DIR"

new_content="// GENERATED by Scripts/generate-secrets.sh — DO NOT EDIT, DO NOT COMMIT.
enum Secrets {
    static let discogsToken = \"${discogs_token}\"
    static let soundCloudClientID = \"${sc_client_id}\"
    static let soundCloudClientSecret = \"${sc_client_secret}\"
}
"

# Write atomically, and only when content changed, so incremental builds stay quiet.
if [ -f "$OUT_FILE" ] && [ "$(cat "$OUT_FILE")" = "$new_content" ]; then
    exit 0
fi

tmp_file="$(mktemp "$OUT_DIR/.Secrets.swift.XXXXXX")"
printf '%s' "$new_content" > "$tmp_file"
mv "$tmp_file" "$OUT_FILE"
